def enqueue(r: redis.Redis, case_id: str) -> str:
    job = {"id": uuid.uuid4().hex[:8],
           "case_id": case_id, "attempt": 1}
    r.rpush(QUEUE, json.dumps(job))  # was lpush
    return job["id"]

def promote_due(r: redis.Redis) -> None:
    now = time.time()
    for raw in r.zrangebyscore(DELAYED, 0, now):
        if r.zrem(DELAYED, raw):
            r.lpush(QUEUE, raw)
